SELECT FROM PHOTO_POSTS PP JOIN USERS U ON U.USER_ID = PP.CREATED_BY LEFT JOIN PHOTO_ALBUMS A ON A.ALBUM_ID = PP.ALBUM_ID WHERE ( (PP.SCOPE_TYPE = #{scopeType} AND PP.SCOPE_ID = #{scopeId}) OR EXISTS ( SELECT 1 FROM CONTENT_SHARES CS WHERE CS.CONTENT_TYPE = 'PHOTO' AND CS.CONTENT_ID = PP.POST_ID AND CS.ACTIVE_YN = 'Y' AND NVL(CS.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED' AND (CS.EXPIRES_AT IS NULL OR CS.EXPIRES_AT >= SYSDATE) AND ( (#{scopeType} = 'WORKSPACE' AND CS.TARGET_TYPE = 'WS' AND CS.TARGET_ID = #{scopeId} AND EXISTS (SELECT 1 FROM WS_MEMBERS WSM WHERE WSM.WS_ID = CS.TARGET_ID AND WSM.USER_ID = #{userId})) OR (#{scopeType} = 'PROJECT' AND CS.TARGET_TYPE = 'PROJ' AND CS.TARGET_ID = #{scopeId} AND EXISTS (SELECT 1 FROM PROJ_MEMBERS PM WHERE PM.PROJ_ID = CS.TARGET_ID AND PM.USER_ID = #{userId})) ) ) ) AND NVL(PP.DELETED_YN, 'N') = 'N'
AND PP.ALBUM_ID = #{albumId}
ORDER BY PP.CREATED_AT DESC, PP.POST_ID DESC

SELECT 
  FROM PHOTO_POSTS PP
  JOIN USERS U ON U.USER_ID = PP.CREATED_BY
  LEFT JOIN PHOTO_ALBUMS A ON A.ALBUM_ID = PP.ORIGINAL_ALBUM_ID
 WHERE NVL(PP.DELETED_YN, 'N') = 'Y'
   AND PP.SCOPE_TYPE = #{scopeType}
   AND PP.SCOPE_ID = #{scopeId}
   AND (
        PP.CREATED_BY = #{userId}
        OR (PP.SCOPE_TYPE = 'WORKSPACE' AND (
            EXISTS (SELECT 1 FROM WORKSPACES W WHERE W.WS_ID = PP.SCOPE_ID AND W.OWNER_ID = #{userId})
            OR EXISTS (SELECT 1 FROM WS_MEMBERS WM WHERE WM.WS_ID = PP.SCOPE_ID AND WM.USER_ID = #{userId} AND UPPER(NVL(WM.WS_ROLE, 'MEMBER')) = 'ADMIN')
        ))
        OR (PP.SCOPE_TYPE = 'PROJECT' AND (
            EXISTS (SELECT 1 FROM PROJECTS P WHERE P.PROJ_ID = PP.SCOPE_ID AND P.LEADER_ID = #{userId})
            OR EXISTS (SELECT 1 FROM PROJ_MEMBERS PM WHERE PM.PROJ_ID = PP.SCOPE_ID AND PM.USER_ID = #{userId} AND UPPER(NVL(PM.PROJ_ROLE, 'MEMBER')) IN ('ADMIN', 'LEADER', 'OWNER', 'PM'))
        ))
   )
 ORDER BY PP.DELETED_AT DESC, PP.POST_ID DESC

