   AND REACTION_TYPE = 'COLLECT'

mapper.insert:
INSERT INTO CONTENT_REACTIONS (
    REACTION_ID, CONTENT_TYPE, CONTENT_ID, USER_ID, REACTION_TYPE, CREATED_AT
)
SELECT SEQ_CONTENT_REACTION_ID.NEXTVAL, 'PHOTO_POST', #{postId}, #{userId}, 'COLLECT', SYSDATE
  FROM DUAL
 WHERE NOT EXISTS (
    SELECT 1
      FROM CONTENT_REACTIONS
     WHERE CONTENT_TYPE = 'PHOTO_POST'
       AND CONTENT_ID = #{postId}
       AND USER_ID = #{userId}
       AND REACTION_TYPE = 'COLLECT'
 )

INSERT INTO CONTENT_REACTIONS (
    REACTION_ID, CONTENT_TYPE, CONTENT_ID, USER_ID, REACTION_TYPE, CREATED_AT
)
SELECT SEQ_CONTENT_REACTION_ID.NEXTVAL, 'PHOTO_COLLECT_LINK', #{collectedPostId}, #{userId}, 'SRC_' || #{sourcePostId}, SYSDATE
  FROM DUAL
 WHERE NOT EXISTS (
    SELECT 1
      FROM CONTENT_REACTIONS
     WHERE CONTENT_TYPE = 'PHOTO_COLLECT_LINK'
       AND CONTENT_ID = #{collectedPostId}
       AND USER_ID = #{userId}
 )

