UPDATE PHOTO_POST_COMMENTS
   SET DELETED_YN = 'Y',
       COMMENT_CONTENT = '삭제된 댓글입니다.',
       UPDATED_AT = SYSDATE
 WHERE COMMENT_ID = #{commentId}
   AND POST_ID = #{postId}
   AND NVL(DELETED_YN, 'N') = 'N'
   AND (
        USER_ID = #{userId}
        OR #{canManage} = 1
   )
